use crate::types::{LoopCandidate, PackOutput};
#[derive(Clone, Debug)] pub struct ExportOptions { pub program_name: String, pub feed_mm_min: f64 }
impl Default for ExportOptions { fn default() -> Self { Self { program_name: "np-pack-stub".into(), feed_mm_min: 600.0 } } }
pub fn emit_gcode_stub(candidates: &[LoopCandidate], output: &PackOutput, opts: &ExportOptions) -> String { let by_id: std::collections::HashMap<&str, &LoopCandidate> = candidates.iter().map(|c| (c.id.as_str(), c)).collect(); let mut out = String::new(); out.push_str(&format!("; np-pack TCP/G-code STUB — {}\n", opts.program_name)); out.push_str("; NOT machine-validated. Placeholder fiber feed commands only.\n"); out.push_str(&format!("; strategy={} status={}\n", output.strategy, output.solver_status)); for note in &output.notes { out.push_str(&format!("; note: {note}\n")); } out.push_str("G21 ; mm\nG90 ; absolute\n"); out.push_str(&format!("F{:.1}\n", opts.feed_mm_min)); let cut_set: std::collections::HashSet<usize> = output.cuts.iter().map(|c| c.after_tour_index).collect(); for (step, id) in output.tour_order.iter().enumerate() { let Some(c) = by_id.get(id.as_str()) else { out.push_str(&format!("; missing candidate id={id}\n")); continue; }; out.push_str(&format!("; --- loop id={} layer={} weight={:.4} length={:.3} ---\n", c.id, c.layer_id, c.weight, c.length)); out.push_str("M700 ; FIBER_ON (placeholder)\n"); for (pi, p) in c.points.iter().enumerate() { if pi == 0 { out.push_str(&format!("G0 X{:.4} Y{:.4}\n", p[0], p[1])); } else { out.push_str(&format!("G1 X{:.4} Y{:.4}\n", p[0], p[1])); } } out.push_str("M701 ; FIBER_OFF (placeholder)\n"); if cut_set.contains(&step) { out.push_str("M702 ; FIBER_CUT (placeholder)\nM703 ; FIBER_RESTART (placeholder)\n"); } } out.push_str("M400 ; wait\n; end stub\n"); out }
